    color: white;
}

.step.completed .step-circle {
    border-color: #2ec4b6;
    background: #2ec4b6;
    color: white;
}

.step.future .step-circle {
    border-color: #ddd;
    background: #f8f9fa;
    color: #999;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ec4b6;
}

.step-connector {
    flex: 1;
    height: 3px;
    background: #ddd;
    min-width: 20px;
    margin: 0 0.25rem;
    margin-bottom: 1.5rem;
    transition: background 0.3s ease;
}

.step-connector.completed {
    background: #2ec4b6;
}

.checkmark {
    font-size: 1rem;
}

/* Form Content */
.step-content {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.7rem 1rem;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    font-size: 1rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
