{"path": "/tmp/sv-e353470498184d2d9c29802cd982b77d/Components/Pages/Apply.razor", "file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_e353470498184d2d9c29802cd982b77d.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < stepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@stepNames[stepIndex]</div>
            </div>
            @if (stepIndex < stepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @if (submitted)
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <p class="application-id"><strong>@applicationId</strong></p>
        </div>
    }
    else
    {
        @* Step 1: Personal Info *@
        @if (currentStep == 0)
        {
            <div class="step-content">
                <h2>Personal Information</h2>
                <div class="form-group">
                    <label>Full Name *</label>
                    <input type="text" @bind="fullName" @bind:event="oninput" placeholder="Enter your full name" />
                    @if (showErrors && string.IsNullOrWhiteSpace(fullName))
                    {
                        <span class="error">Full name is required.</span>
                    }
                </div>
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" @bind="email" @bind:event="oninput" placeholder="Enter your email" />
                    @if (showErrors && string.IsNullOrWhiteSpace(email))
                    {
                        <span class="error">Email is required.</span>
                    }
                    @if (!string.IsNullOrEmpty(emailError))
                    {
                        <span class="error">@emailError</span>
                    }
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" @bind="phone" @bind:event="oninput" placeholder="Enter your phone number" />
                    @if (showErrors && string.IsNullOrWhiteSpace(phone))
                    {
                        <span class="error">Phone is required.</span>
                    }
                </div>
                <div class="form-group">
                    <label>Address *</label>
                    <input type="text" @bind="address" @bind:event="oninput" placeholder="Enter your address" />
                    @if (showErrors && string.IsNullOrWhiteSpace(address))
                    {
                        <span class="error">Address is required.</span>
                    }
                </div>
                <div class="form-buttons">
                    <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@isValidating">
                        @if (isValidating)
                        {
                            <span>Validating...</span>
                        }
                        else
                        {
                            <span>Next</span>
                        }
                    </button>
                </div>
            </div>
        }

        @* Step 2: Work History *@
        @if (currentStep == 1)
        {
            <div class="step-content">
                <h2>Work History</h2>
                @for (int i = 0; i < workEntries.Count; i++)
                {
                    var index = i;
                    <div class="work-entry-card">
                        <div class="work-entry-header">
                            <h3>Position @(index + 1)</h3>
                            @if (workEntries.Count > 1)
                            {
                                <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="form-group">
                            <label>Company Name *</label>
                            <input type="text" @bind="workEntries[index].Company" @bind:event="oninput" placeholder="Company name" />
                        </div>
                        <div class="form-group">
                            <label>Job Title *</label>
                            <input type="text" @bind="workEntries[index].Title" @bind:event="oninput" placeholder="Job title" />
                        </div>
                        <div class="form-row">
                            <div class="form-group">
                                <label>Start Date *</label>
                                <input type="date" @bind="workEntries[index].StartDate" />
                            </div>
                            <div class="form-group">
                                <label>End Date</label>
                                <input type="date" @bind="workEntries[index].EndDate" disabled="@workEntries[index].IsCurrent" />
                            </div>
                        </div>
                        <div class="form-group checkbox-group">
                            <label>
                                <input type="checkbox" @bind="workEntries[index].IsCurrent" />
                                Currently working here
                            </label>
                        </div>
                        <div class="form-group">
                            <label>Description</label>
                            <textarea @bind="workEntries[index].Description" @bind:event="oninput" placeholder="Describe your responsibilities..." rows="3"></textarea>
                        </div>
                    </div>
                }
                @if (showErrors && !IsWorkHistoryValid())
                {
                    <span class="error">Each position must have a company name, job title, and start date.</span>
                }
                <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
                <div class="form-buttons">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
                </div>
            </div>
        }

        @* Step 3: References *@
        @if (currentStep == 2)
        {
            <div class="step-content">
                <h2>References</h2>
                @for (int i = 0; i < references.Count; i++)
                {
                    var index = i;
                    <div class="reference-card">
                        <div class="work-entry-header">
                            <h3>Reference @(index + 1)</h3>
                            @if (references.Count > 2)
                            {
                                <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="form-group">
                            <label>Name *</label>
                            <input type="text" @bind="references[index].Name" @bind:event="oninput" placeholder="Reference name" />
                        </div>
                        <div class="form-group">
                            <label>Relationship *</label>
                            <input type="text" @bind="references[index].Relationship" @bind:event="oninput" placeholder="e.g., Former Manager" />
                        </div>
                        <div class="form-group">
                            <label>Email *</label>
                            <input type="email" @bind="references[index].Email" @bind:event="oninput" placeholder="Reference email" />
                        </div>
                        <div class="form-group">
                            <label>Phone *</label>
                            <input type="tel" @bind="references[index].Phone" @bind:event="oninput" placeholder="Reference phone" />
                        </div>
                    </div>
                }
                @if (showErrors && !IsReferencesValid())
                {
                    <span class="error">Each reference must have all fields filled in.</span>
                }
                @if (references.Count < 3)
                {
                    <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
                }
                <div class="form-buttons">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-next" @onclick="NextFromReferences">Next</button>
                </div>
            </div>
        }

        @* Step 4: Cover Letter *@
        @if (currentStep == 3)
        {
            <div class="step-content">
                <h2>Cover Letter</h2>
                <div class="form-group">
                    <label>Write your cover letter</label>
                    <textarea @bind="coverLetter" @bind:event="oninput" placeholder="Tell us why you're a great fit..." rows="12" maxlength="2000"></textarea>
                    <div class="char-count">@coverLetter.Length / 2000 characters</div>
                </div>
                @if (showErrors && string.IsNullOrWhiteSpace(coverLetter))
                {
                    <span class="error">Cover letter is required.</span>
                }
                <div class="form-buttons">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-next" @onclick="NextFromCoverLetter">Next</button>
                </div>
            </div>
        }

        @* Step 5: Review & Submit *@
        @if (currentStep == 4)
        {
            <div class="step-content">
                <h2>Review & Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <dl>
                        <dt>Full Name</dt><dd>@fullName</dd>
                        <dt>Email</dt><dd>@email</dd>
                        <dt>Phone</dt><dd>@phone</dd>
                        <dt>Address</dt><dd>@address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    @foreach (var entry in workEntries)
                    {
                        <div class="review-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p>@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var reference in references)
                    {
                        <div class="review-entry">
                            <strong>@reference.Name</strong> (@reference.Relationship)<br />
                            <span>@reference.Email | @reference.Phone</span>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    <p class="cover-letter-preview">@coverLetter</p>
                </div>

                @if (!string.IsNullOrEmpty(submitError))
                {
                    <div class="error">@submitError</div>
                }

                <div class="form-buttons">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@isSubmitting">
                        @if (isSubmitting)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            </div>
        }
    }
</div>

@code {
    private readonly string[] stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int currentStep = 0;
    private bool showErrors = false;
    private bool isValidating = false;
    private bool isSubmitting = false;
    private bool submitted = false;
    private int applicationId;
    private string? emailError;
    private string? submitError;

    // Step 1: Personal Info
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2: Work History
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string coverLetter = "";

    private string GetStepClass(int step)
    {
        if (step == currentStep) return "active";
        if (IsStepCompleted(step)) return "completed";
        return "future";
    }

    private bool IsStepCompleted(int step)
    {
        return step < currentStep;
    }

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
            showErrors = false;
            emailError = null;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        showErrors = true;
        emailError = null;

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            return;
        }

        isValidating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(email);
            if (!isValid)
            {
                emailError = "Email address is not valid.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        showErrors = false;
        currentStep = 1;
    }

    private void NextFromWorkHistory()
    {
        showErrors = true;
        if (!IsWorkHistoryValid()) return;
        showErrors = false;
        currentStep = 2;
    }

    private void NextFromReferences()
    {
        showErrors = true;
        if (!IsReferencesValid()) return;
        showErrors = false;
        currentStep = 3;
    }

    private void NextFromCoverLetter()
    {
        showErrors = true;
        if (string.IsNullOrWhiteSpace(coverLetter)) return;
        showErrors = false;
        currentStep = 4;
    }

    private void PreviousStep()
    {
        showErrors = false;
        emailError = null;
        if (currentStep > 0)
            currentStep--;
    }

    private bool IsWorkHistoryValid()
    {
        return workEntries.All(e =>
            !string.IsNullOrWhiteSpace(e.Company) &&
            !string.IsNullOrWhiteSpace(e.Title) &&
            e.StartDate != default);
    }

    private bool IsReferencesValid()
    {
        return references.All(r =>
            !string.IsNullOrWhiteSpace(r.Name) &&
            !string.IsNullOrWhiteSpace(r.Relationship) &&
            !string.IsNullOrWhiteSpace(r.Email) &&
            !string.IsNullOrWhiteSpace(r.Phone));
    }

    private void AddWorkEntry()
    {
        workEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var refs = references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            submitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
"}

